import {
    _decorator, Component, Node, Vec3, input, Input, EventKeyboard, KeyCode, Quat,
} from 'cc';
import { PlayerStats } from './PlayerStats';
import { Enemy } from '../enemies/Enemy';
import { EventBus, GameEvents } from '../core/EventBus';
const { ccclass } = _decorator;

export interface SkillDef {
    id: string;
    name: string;
    desc: string;
    cooldown: number;
    mpCost: number;
    range: number;
    damageMul: number;   // multiplier on player.attack
    aoeRadius?: number;  // if set, AOE
    color: string;       // ui color
    key: KeyCode;
}

export const DefaultSkills: SkillDef[] = [
    { id: 'slash',  name: 'Heavy Slash',  desc: 'Powerful frontal slash.',           cooldown: 1.5, mpCost: 0,  range: 2.5, damageMul: 1.8, color: '#ffc24a', key: KeyCode.KEY_Q },
    { id: 'whirl',  name: 'Whirlwind',    desc: 'AOE spin attack around you.',       cooldown: 6,   mpCost: 15, range: 0,   damageMul: 1.3, aoeRadius: 3.5, color: '#9be36b', key: KeyCode.KEY_E },
    { id: 'fire',   name: 'Fire Burst',   desc: 'Ranged fire burst with AOE.',       cooldown: 8,   mpCost: 25, range: 9,   damageMul: 2.4, aoeRadius: 2.5, color: '#ff7a3a', key: KeyCode.KEY_R },
    { id: 'heal',   name: 'Battle Heal',  desc: 'Heal yourself for 40 HP.',          cooldown: 12,  mpCost: 30, range: 0,   damageMul: 0,   color: '#7ad4ff', key: KeyCode.KEY_F },
];

@ccclass('PlayerCombat')
export class PlayerCombat extends Component {
    public stats: PlayerStats | null = null;
    public enemies: Enemy[] = [];
    public skills: SkillDef[] = DefaultSkills.slice();
    public cooldowns: number[] = [0, 0, 0, 0];
    public attackCooldown = 0;

    onLoad() {
        input.on(Input.EventType.KEY_DOWN, this.onKey, this);
    }
    onDestroy() {
        input.off(Input.EventType.KEY_DOWN, this.onKey, this);
    }

    private onKey(e: EventKeyboard) {
        if (e.keyCode === KeyCode.KEY_J) {
            this.basicAttack();
        }
        for (let i = 0; i < this.skills.length; i++) {
            if (e.keyCode === this.skills[i].key) this.useSkill(i);
        }
    }

    update(dt: number) {
        if (this.attackCooldown > 0) this.attackCooldown -= dt;
        for (let i = 0; i < this.cooldowns.length; i++) {
            if (this.cooldowns[i] > 0) {
                this.cooldowns[i] -= dt;
                if (this.cooldowns[i] < 0) this.cooldowns[i] = 0;
                EventBus.emit(GameEvents.SKILL_COOLDOWN_CHANGED, i, this.cooldowns[i], this.skills[i].cooldown);
            }
        }
    }

    private getForward(): Vec3 {
        const e = new Vec3();
        Quat.toEuler(e, this.node.worldRotation);
        const r = e.y * Math.PI / 180;
        return new Vec3(Math.sin(r), 0, Math.cos(r));
    }

    private findEnemiesInArc(origin: Vec3, fwd: Vec3, range: number, halfAngleDeg = 60): Enemy[] {
        const res: Enemy[] = [];
        const cosA = Math.cos(halfAngleDeg * Math.PI / 180);
        for (const en of this.enemies) {
            if (!en || !en.isValid || en.dead) continue;
            const p = en.node.worldPosition;
            const dx = p.x - origin.x, dz = p.z - origin.z;
            const d = Math.hypot(dx, dz);
            if (d > range) continue;
            const dot = (dx * fwd.x + dz * fwd.z) / Math.max(0.0001, d);
            if (dot >= cosA) res.push(en);
        }
        return res;
    }

    private findEnemiesInRadius(center: Vec3, radius: number): Enemy[] {
        const res: Enemy[] = [];
        for (const en of this.enemies) {
            if (!en || !en.isValid || en.dead) continue;
            const p = en.node.worldPosition;
            const d = Math.hypot(p.x - center.x, p.z - center.z);
            if (d <= radius) res.push(en);
        }
        return res;
    }

    basicAttack() {
        if (!this.stats || this.attackCooldown > 0) return;
        this.attackCooldown = 0.35;
        const fwd = this.getForward();
        const targets = this.findEnemiesInArc(this.node.worldPosition, fwd, 2.2, 55);
        const dmg = this.stats.attack;
        for (const t of targets) t.takeDamage(dmg, this.node.worldPosition);
        EventBus.emit(GameEvents.SKILL_USED, -1, 'Attack');
    }

    useSkill(i: number) {
        if (!this.stats) return;
        const skill = this.skills[i];
        if (!skill) return;
        if (this.cooldowns[i] > 0) return;
        if (skill.mpCost > 0 && !this.stats.useMP(skill.mpCost)) return;

        this.cooldowns[i] = skill.cooldown;
        EventBus.emit(GameEvents.SKILL_USED, i, skill.name);
        EventBus.emit(GameEvents.SKILL_COOLDOWN_CHANGED, i, this.cooldowns[i], skill.cooldown);

        const baseDmg = this.stats.attack * skill.damageMul;
        const fwd = this.getForward();
        const origin = this.node.worldPosition;

        switch (skill.id) {
            case 'slash': {
                const targets = this.findEnemiesInArc(origin, fwd, skill.range, 50);
                for (const t of targets) t.takeDamage(baseDmg, origin);
                break;
            }
            case 'whirl': {
                const targets = this.findEnemiesInRadius(origin, skill.aoeRadius!);
                for (const t of targets) t.takeDamage(baseDmg, origin);
                break;
            }
            case 'fire': {
                // pick best forward target
                const arc = this.findEnemiesInArc(origin, fwd, skill.range, 35);
                const center = arc.length
                    ? arc.reduce((a, b) => {
                        const da = Vec3.squaredDistance(origin, a.node.worldPosition);
                        const db = Vec3.squaredDistance(origin, b.node.worldPosition);
                        return da < db ? a : b;
                    }).node.worldPosition.clone()
                    : new Vec3(origin.x + fwd.x * skill.range, origin.y, origin.z + fwd.z * skill.range);
                const targets = this.findEnemiesInRadius(center, skill.aoeRadius!);
                for (const t of targets) t.takeDamage(baseDmg, origin);
                break;
            }
            case 'heal': {
                this.stats.heal(40);
                break;
            }
        }
    }
}